components.css:
.ds-primary { font-family: "DM Sans", Inter, ui-sans-serif, system-ui, sans-serif; display: inline-flex; align-items: center; justify-content: center; gap: 8px; padding: 10px 16px; border: 0; border-radius: 12px; background: #25563b; color: #fff; font-size: 14px; line-height: 20px; font-weight: 600; transition: background-color 150ms; }
.ds-primary:hover { background: #1e4731; }
.ds-primary:focus-visible { outline: 2px solid var(--focus, #457a51); outline-offset: 4px; }
.ds-primary:disabled { opacity: .6; cursor: not-allowed; }
:host-context(.dark) .ds-primary { background: #a7cd8f; color: #151d17; }
:host-context(.dark) .ds-primary:hover { background: #c3e5a6; }

.ds-secondary { font-family: "DM Sans", Inter, ui-sans-serif, system-ui, sans-serif; display: inline-flex; align-items: center; justify-content: center; gap: 8px; padding: 10px 16px; border: 1px solid var(--line, #dce1d5); border-radius: 12px; background: transparent; color: var(--ink, #202920); font-size: 14px; line-height: 20px; font-weight: 500; transition: background-color 150ms; }
.ds-secondary:hover { background: var(--soft-green, #e7efde); }
.ds-secondary:focus-visible { outline: 2px solid var(--focus, #457a51); outline-offset: 4px; }
.ds-secondary:disabled { opacity: .6; cursor: not-allowed; }

.ds-small { font-family: "DM Sans", Inter, ui-sans-serif, system-ui, sans-serif; display: inline-flex; align-items: center; gap: 6px; padding: 6px 10px; border: 1px solid var(--line, #dce1d5); border-radius: 9px; background: transparent; color: var(--ink, #202920); font-size: 12px; line-height: 16px; font-weight: 500; transition: background-color 150ms; }
.ds-small:hover { background: var(--soft-green, #e7efde); }
.ds-small:focus-visible { outline: 2px solid var(--focus, #457a51); outline-offset: 4px; }
.ds-small:disabled { opacity: .6; cursor: not-allowed; }

.ds-study-backdrop { padding: 14px; border-radius: 16px; background: var(--hero, #183627); }
.ds-study { font-family: "DM Sans", Inter, ui-sans-serif, system-ui, sans-serif; display: inline-flex; align-items: center; justify-content: center; gap: 9px; min-height: 46px; padding: 9px 14px; border: 0; border-radius: 9px; background: var(--lime, #d9edaa); color: #18291f; font-size: 14px; font-weight: 700; }
.ds-study:hover { background: #ecf8cc; }
.ds-study:focus-visible { outline: 2px solid #f1fad5; outline-offset: 4px; }
.ds-study svg:last-child { margin-left: 12px; }

.ds-field { font-family: "DM Sans", Inter, ui-sans-serif, system-ui, sans-serif; display: grid; gap: 4px; color: var(--ink, #202920); font-size: 14px; line-height: 20px; }
.ds-field input { font: inherit; padding: 10px 16px; border: 1px solid var(--line, #dce1d5); border-radius: 12px; background: transparent; color: inherit; }
.ds-field input::placeholder { color: var(--muted, #556254); }
.ds-field input:focus { outline: none; border-color: #25563b; box-shadow: 0 0 0 2px rgb(37 86 59 / .3); }

.ds-status-group { display: flex; align-items: center; flex-wrap: wrap; gap: 8px; }
.ds-status { font-family: "DM Sans", Inter, ui-sans-serif, system-ui, sans-serif; padding: 2px 8px; border-radius: 999px; background: rgb(85 98 84 / .15); color: var(--muted, #556254); font-size: 12px; line-height: 16px; font-weight: 500; }
.ds-status-published { background: rgb(16 185 129 / .15); color: #047857; }
.ds-status-review { background: rgb(245 158 11 / .15); color: #b45309; }
:host-context(.dark) .ds-status-published { color: #6ee7b7; }
:host-context(.dark) .ds-status-review { color: #fcd34d; }

.ds-nav { font-family: "DM Sans", Inter, ui-sans-serif, system-ui, sans-serif; display: grid; gap: 4px; padding: 15px; border-radius: 9px; background: var(--rail, #18291f); color: var(--rail-text, #d7e2d6); }
.ds-nav button { display: flex; align-items: center; gap: 12px; min-height: 44px; padding: 8px 12px; border: 0; border-radius: 9px; background: transparent; color: inherit; font: inherit; font-size: 14px; font-weight: 600; text-align: left; transition: background-color 140ms, color 140ms; }
.ds-nav button svg { width: 19px; height: 19px; flex: none; stroke-width: 1.8; }
.ds-nav button:hover { background: #2b4333; color: #fff; }
.ds-nav button[aria-current="page"] { background: var(--lime, #d9edaa); color: #193325; }
.ds-nav button:focus-visible { outline: 2px solid #f1fad5; outline-offset: 4px; }

.ds-panel { font-family: "DM Sans", Inter, ui-sans-serif, system-ui, sans-serif; padding: 20px; border: 1px solid var(--line, #dce1d5); border-radius: 15px; background: var(--panel, #fffef8); color: var(--ink, #202920); }
.ds-panel p { margin: 4px 0 0; color: var(--muted, #556254); font-size: 14px; line-height: 20px; }
@media (min-width: 640px) { .ds-panel { padding: 24px; } }

.ds-course-list { border: 1px solid var(--line, #dce1d5); border-radius: 13px; background: var(--panel, #fffef8); overflow: hidden; }
.ds-course-row { font-family: "DM Sans", Inter, ui-sans-serif, system-ui, sans-serif; display: flex; align-items: center; width: 100%; min-height: 64px; gap: 12px; padding: 13px; border: 0; background: transparent; color: var(--green, #25563b); text-align: left; }
.ds-course-row:hover { background: var(--soft-green, #e7efde); }
.ds-course-row:focus-visible { outline: 2px solid var(--focus, #457a51); outline-offset: -3px; }
.ds-course-row > svg { flex: none; }
.ds-course-icon { display: grid; place-items: center; flex: none; width: 40px; height: 40px; border-radius: 8px; background: var(--soft-green, #e7efde); }
.ds-course-icon svg { width: 20px; height: 20px; }
.ds-course-title { min-width: 0; flex: 1; }
.ds-course-title strong { display: block; color: var(--ink, #202920); font-size: 14px; line-height: 1.35; }
.ds-course-title small { display: block; margin-top: 4px; color: var(--muted, #556254); font-size: 12px; }

.ds-progress { font-family: "DM Sans", Inter, ui-sans-serif, system-ui, sans-serif; padding: 14px; border-radius: 16px; background: var(--hero, #183627); }
.ds-progress div { display: flex; justify-content: space-between; gap: 12px; max-width: 340px; color: #c9dac9; font-size: 13px; }
.ds-progress strong { color: #f3f7e8; font-variant-numeric: tabular-nums; }
.ds-progress progress { display: block; width: 100%; max-width: 340px; height: 6px; margin-top: 8px; overflow: hidden; border: 0; border-radius: 999px; background: #54705d; color: var(--lime, #d9edaa); }
.ds-progress progress::-webkit-progress-bar { background: #54705d; }
.ds-progress progress::-webkit-progress-value { background: var(--lime, #d9edaa); }
.ds-progress progress::-moz-progress-bar { background: var(--lime, #d9edaa); }
